    ["desktop-wide floating", 1280, 1200, false],
    ["narrow floating", 1280, 600, true],
    ["mobile viewport", 390, 390, true],
  ])("commits the requested thread before its session list resolves on %s", (_surface, viewportWidth, width, narrow) => {
