    render(
      <ChatView
        projectId="project-a"
        addToast={vi.fn()}
        compactLayout
        initialDirectSession={session()}
        initialDirectSessionNonce={1}
        persistChatPreferences={false}
        onOpenSessionInNewWindow={vi.fn()}
